package hu.laci.cms.backend.dao.content;
import hu.laci.cms.backend.dao.common.BaseDao; import hu.laci.cms.backend.model.common.QuerySpec; import hu.laci.cms.backend.model.content.*; import hu.laci.cms.backend.model.site.Site; import java.util.*;
/** JDBC persistence for saved collection definitions. */ public class ContentCollectionDaoImpl extends BaseDao<ContentCollection,ContentCollectionProperty> implements ContentCollectionDao { public ContentCollectionDaoImpl(){super(ContentCollection.class);} public long countBySite(Site s){return findCustomOne("countCollections","SELECT COUNT(*) AS row_count FROM content_collections WHERE site_id=?",List.of(s),r->r.getLong("row_count"),"Failed to count collections.").orElse(0L);} public List<ContentCollection> findBySite(Site s){return findAll(QuerySpec.<ContentCollectionProperty>create().where(ContentCollectionProperty.SITE).equalsTo(s).orderBy(ContentCollectionProperty.CODE.asc()));} public Optional<ContentCollection> findBySiteAndId(Site s,Long id){return findAll(QuerySpec.<ContentCollectionProperty>create().where(ContentCollectionProperty.SITE).equalsTo(s).where(ContentCollectionProperty.ID).equalsTo(id)).stream().findFirst();} public Optional<ContentCollection> findBySiteAndCode(Site s,String c){return findAll(QuerySpec.<ContentCollectionProperty>create().where(ContentCollectionProperty.SITE).equalsTo(s).where(ContentCollectionProperty.CODE).equalsTo(c)).stream().findFirst();}}
